BEGIN;
UPDATE public.tutorials SET titre='Configurer sa caisse POS — TPE & ticket', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-configurer-sa-caisse-pos-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-configurer-sa-caisse-pos-thumbnail', duree_secondes=44, how_it_works=ARRAY['Déclarez vos îlots d''encaissement : un comptoir, une terrasse, un bar sont trois points de vente distincts.','Appairez chaque terminal Smile&Pay à son îlot, et désignez celui qui sert par défaut.','Renseignez l''en-tête du ticket : raison sociale, adresse, numéro de TVA. Ce sont les mentions obligatoires.','Testez un encaissement à un euro, puis annulez-le : c''est le seul moyen de vérifier la chaîne complète avant le service.']::text[], what_its_for='Une caisse mal déclarée se voit au premier service : le TPE ne répond pas, le ticket sort sans mentions légales, et personne ne sait quel terminal a encaissé quoi. Ce réglage se fait une fois, et il porte tout le reste.', astuce_du_chef='Nommez vos terminaux par leur place réelle — « Comptoir », « Terrasse » — jamais par leur numéro de série. Le jour où un écart apparaît, vous cherchez un endroit, pas un numéro.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Liste mes terminaux de paiement pour l''établissement [ID] : libellé, îlot, lequel est actif par défaut, et la date de dernière utilisation."}]'::jsonb, statut='brouillon' WHERE slug='configurer-sa-caisse-pos';
UPDATE public.tutorials SET titre='Ouvrir son fond de caisse en début de service', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-ouvrir-son-fond-de-caisse-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-ouvrir-son-fond-de-caisse-thumbnail', duree_secondes=42, how_it_works=ARRAY['Choisissez l''opérateur : seul un employé disposant de la permission caisse peut ouvrir une session.','Comptez le fond de caisse réel et saisissez-le, au centime. C''est la référence de tout l''écart de ce soir.','Validez : la session s''ouvre, et chaque encaissement s''y rattache automatiquement.','Une seule session à la fois par établissement : si elle est déjà ouverte, c''est la précédente qu''il faut clôturer.']::text[], what_its_for='Tant que la session n''est pas ouverte, aucun encaissement ne se rattache à personne ni à un fond de départ. L''écart de fin de service devient alors inexplicable — non pas grand, mais impossible à attribuer.', astuce_du_chef='Saisissez le fond compté, pas le fond théorique. Reporter le montant d''hier parce que « ça n''a pas bougé » revient à effacer l''écart d''hier dans celui d''aujourd''hui.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Ouvre la caisse de l''établissement [ID] avec un fond de [MONTANT] euros, opérateur [ID EMPLOYÉ]."}]'::jsonb, statut='brouillon' WHERE slug='ouvrir-son-fond-de-caisse';
UPDATE public.tutorials SET titre='Encaisser une commande — comptoir & table', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-encaisser-une-commande-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-encaisser-une-commande-thumbnail', duree_secondes=43, how_it_works=ARRAY['Ouvrez la note, au comptoir ou à la table : le reste dû s''affiche.','Choisissez le moyen : espèces, carte, titre-restaurant ou chèque.','En espèces, saisissez le montant remis — le rendu se calcule tout seul.','Le titre-restaurant ne rend jamais la monnaie : le surplus est perdu pour le client, jamais rendu en pièces.','La note se solde d''elle-même quand le reste dû atteint zéro.']::text[], what_its_for='Encaisser, ce n''est pas enregistrer un total : c''est faire tomber le reste dû à zéro. Tant qu''il ne l''est pas, la note reste ouverte — et c''est cette règle qui rend possibles les paiements partagés et les acomptes.', astuce_du_chef='Saisissez toujours le montant réellement remis, même quand il est rond. C''est ce chiffre qui alimente le rendu, et c''est lui qu''on relit quand un écart apparaît le soir.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Encaisse la commande [ID] de l''établissement [ID] : [MONTANT] euros en [especes / carte / titre_restaurant / cheque], opérateur [ID EMPLOYÉ]. Pour des espèces, indique aussi le montant remis par le client."}]'::jsonb, statut='brouillon' WHERE slug='encaisser-une-commande';
UPDATE public.tutorials SET titre='Appliquer une remise et des avoirs', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-appliquer-une-remise-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-appliquer-une-remise-thumbnail', duree_secondes=35, how_it_works=ARRAY['Appliquez la remise sur la note avant l''encaissement, jamais après : une note soldée ne se remise plus.','Choisissez le motif — geste commercial, plat non conforme, avoir. C''est lui qu''on relit dans le rapport.','Un avoir se pose sur la note suivante du même client : c''est une créance, pas une ristourne.','Le rapport de caisse totalise les remises à part du chiffre d''affaires : la marge reste lisible.']::text[], what_its_for='Une remise accordée de tête et non saisie disparaît deux fois : du ticket du client, et du rapport de caisse. À la fin du mois, le chiffre manque et personne ne sait pourquoi.', astuce_du_chef='Une remise sans motif est une remise perdue. Le montant, on le retrouve ; la raison, jamais — et c''est la raison qui dit s''il faut changer le plat ou changer le fournisseur.', claude_prompts='[]'::jsonb, statut='brouillon' WHERE slug='appliquer-une-remise';
UPDATE public.tutorials SET titre='Séparer une addition — multi-paiement', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-separer-une-addition-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-separer-une-addition-thumbnail', duree_secondes=43, how_it_works=ARRAY['Gardez une seule note : c''est elle qui porte les plats et le total.','Encaissez un premier paiement partiel — le reste dû se recalcule immédiatement.','Changez de moyen entre deux paiements : carte pour l''un, espèces pour l''autre, titre-restaurant pour un troisième.','Répétez jusqu''à zéro : la note se solde à l''instant où le reste dû est couvert.','Relisez la liste des paiements : chaque part, son moyen, son rendu.']::text[], what_its_for='Une table de six qui paie en trois fois, c''est trois paiements sur une seule note — pas trois notes. La différence compte : une seule commande part en cuisine, une seule facture sort, et le reste dû se recalcule tout seul.', astuce_du_chef='Ne créez jamais plusieurs notes pour partager une addition. Vous doubleriez la commande en cuisine et vous perdriez le total réel de la table.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Montre-moi les paiements de la commande [ID] pour l''établissement [ID] : les modes, les montants, le rendu et le reste dû."}]'::jsonb, statut='brouillon' WHERE slug='separer-une-addition';
UPDATE public.tutorials SET titre='Clôturer sa caisse — le Z de caisse', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-cloturer-sa-caisse-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-cloturer-sa-caisse-thumbnail', duree_secondes=40, how_it_works=ARRAY['Lisez le rapport X avant de compter : c''est l''état de la session en cours, chiffre d''affaires, modes de paiement, TVA, remises.','Comptez les espèces en caisse et saisissez le montant compté.','Confirmez : l''écart se calcule entre le théorique et le compté.','Le rapport Z est alors figé. Il ne se recalcule plus, même si une correction arrive après.']::text[], what_its_for='La clôture n''est pas une formalité de fin de service : c''est elle qui fige le chiffre d''affaires du jour, sa ventilation de TVA et son écart. Une session qu''on oublie de fermer emporte le service du lendemain avec elle.', astuce_du_chef='Lisez toujours le X avant de compter, jamais après. Connaître le montant théorique avant de compter, c''est se donner une chance de compter deux fois quand ça ne tombe pas juste.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Résume-moi le rapport X de la caisse de l''établissement [ID], puis clôture la session avec un comptage espèces de [MONTANT] euros, opérateur [ID EMPLOYÉ]."}]'::jsonb, statut='brouillon' WHERE slug='cloturer-sa-caisse';
UPDATE public.tutorials SET titre='Suivre les écarts de caisse — historique', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-suivre-les-ecarts-de-caisse-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-suivre-les-ecarts-de-caisse-thumbnail', duree_secondes=38, how_it_works=ARRAY['Ouvrez l''historique des sessions clôturées : chacune porte son rapport Z.','Comparez l''écart par session, pas seulement son montant : son signe compte autant.','Ventilez par opérateur : un écart qui suit une personne n''a pas la même cause qu''un écart qui suit un service.','Ventilez par moyen de paiement : un écart qui ne touche que les espèces désigne le rendu de monnaie.']::text[], what_its_for='Un écart isolé ne dit rien : on rend mal la monnaie, ça arrive. C''est la répétition qui parle — toujours le même opérateur, toujours le même service, toujours le même sens.', astuce_du_chef='Un écart toujours négatif du même montant n''est presque jamais un vol : c''est un fond de caisse mal saisi à l''ouverture, qui se reproduit chaque jour.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Donne-moi le rapport Z de la session [ID SESSION] de l''établissement [ID] : chiffre d''affaires, ticket moyen, ventilation par mode et par opérateur, TVA, remises."}]'::jsonb, statut='brouillon' WHERE slug='suivre-les-ecarts-de-caisse';
UPDATE public.tutorials SET titre='Connecter son HubRise à FoodEatUp', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-connecter-son-hubrise-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-connecter-son-hubrise-thumbnail', duree_secondes=44, how_it_works=ARRAY['Créez ou reliez votre compte HubRise depuis FoodEatUp.','Choisissez la location : c''est le point de vente précis, pas l''enseigne. Une erreur ici envoie les commandes au mauvais établissement.','Autorisez le connecteur, puis vérifiez son état : connecté, location reconnue.','Contrôlez enfin les commandes du jour restées en attente côté plateformes — elles disent si le flux passe vraiment.']::text[], what_its_for='HubRise est le point de passage : c''est lui qui parle aux plateformes de livraison, et FoodEatUp qui parle à HubRise. Une seule connexion à tenir, au lieu d''une par plateforme.', astuce_du_chef='Vérifiez la location avant tout le reste. Une enseigne à deux adresses a deux locations, et rien dans l''interface ne vous dira que vous avez choisi la mauvaise.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Donne-moi l''état du connecteur HubRise de l''établissement [ID] : connexion, location, plats bloqués au push, commandes du jour en attente côté plateformes."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='connecter-son-hubrise';
UPDATE public.tutorials SET titre='Relier Uber Eats & Deliveroo via HubRise', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-relier-uber-eats-et-deliveroo-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-relier-uber-eats-et-deliveroo-thumbnail', duree_secondes=33, how_it_works=ARRAY['Reliez chaque plateforme depuis votre compte HubRise, l''une après l''autre.','Rattachez-les à la même location que celle choisie pour FoodEatUp.','Attendez une première commande réelle : c''est le seul test qui vaille.','Vérifiez qu''elle apparaît bien dans vos commandes, avec son canal d''origine.']::text[], what_its_for='Chaque plateforme se relie une fois, à HubRise, pas à FoodEatUp. Les commandes descendent ensuite dans la liste unique — mêmes statuts, même cuisine, même comptabilité que les commandes sur place.', astuce_du_chef='Ne testez pas avec une commande fictive passée depuis votre propre téléphone hors zone de livraison : elle est refusée par la plateforme avant d''atteindre HubRise, et vous conclurez à tort que le lien ne marche pas.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Vérifie l''état HubRise de l''établissement [ID], puis liste les commandes du jour pour voir celles qui viennent des plateformes."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='relier-uber-eats-et-deliveroo';
UPDATE public.tutorials SET titre='Synchroniser sa caisse tierce via HubRise', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-synchroniser-sa-caisse-tierce-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-synchroniser-sa-caisse-tierce-thumbnail', duree_secondes=35, how_it_works=ARRAY['Renseignez la référence — le sku_ref — de chaque plat de votre carte.','Reprenez exactement la référence de la caisse tierce : une majuscule d''écart suffit à casser le lien.','Relancez la synchronisation.','Relisez l''état du connecteur : il liste nommément les plats sans référence, donc bloqués.']::text[], what_its_for='La synchronisation ne tient qu''à une chose : la référence de chaque plat. Sans elle, le plat existe des deux côtés sans que rien ne les relie, et il est purement et simplement bloqué au push.', astuce_du_chef='Traitez la liste des plats sans référence comme une liste de courses : tant qu''elle n''est pas vide, la carte est incomplète chez le client, et personne ne vous le signalera.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Liste les plats de l''établissement [ID] qui n''ont pas de sku_ref et sont donc bloqués au push HubRise."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='synchroniser-sa-caisse-tierce';
UPDATE public.tutorials SET titre='Centraliser les commandes — flux livraison', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-centraliser-les-commandes-livraison-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-centraliser-les-commandes-livraison-thumbnail', duree_secondes=39, how_it_works=ARRAY['Ouvrez vos commandes : toutes y sont, tous canaux confondus.','Filtrez par canal pour isoler la livraison — sur place, vitrine, téléphone, agent vocal, plateformes.','Suivez le statut comme pour n''importe quelle commande : en attente, confirmée, en préparation, prête, livrée.','Surveillez les commandes du jour restées en attente côté plateformes : ce sont celles qui n''ont pas franchi le connecteur.']::text[], what_its_for='Une commande de plateforme n''est pas une commande à part : elle entre dans la même liste, avec les mêmes statuts, et part en cuisine par le même chemin. Ce qui change, c''est son canal — et c''est la seule chose à savoir.', astuce_du_chef='Ne traitez pas les commandes de livraison sur un écran séparé. Un service qui regarde deux listes en oublie une, toujours la même, toujours au coup de feu.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Liste les commandes du jour de l''établissement [ID], canal par canal, et signale celles encore en attente côté plateformes."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='centraliser-les-commandes-livraison';
UPDATE public.tutorials SET titre='Gérer une commande en direct sur le KDS', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-gerer-une-commande-en-direct-kds-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-gerer-une-commande-en-direct-kds-thumbnail', duree_secondes=46, how_it_works=ARRAY['Le ticket arrive au poste concerné dès que la commande est confirmée.','Faites avancer chaque plat séparément : à faire, en cours, prêt, servi.','Passez un plat en « en cours » quand vous le commencez, pas quand vous le voyez : c''est ce qui rend le compteur d''attente juste.','« Prêt » l''envoie au pass. Le ticket ne disparaît qu''une fois tous ses plats servis.','La charge des postes se met à jour à chaque changement : elle dit où ça bloque, en direct.']::text[], what_its_for='Le KDS ne suit pas des commandes, il suit des plats. C''est ce qui permet à une entrée de partir pendant qu''un plat chaud cuit encore, sans que le ticket entier attende le plus lent.', astuce_du_chef='Le passage en « en cours » est le seul geste que personne ne fait spontanément — et c''est le seul qui rende le temps d''attente crédible. Sans lui, tout paraît prêt d''un coup.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Passe le plat [ID ITEM] de l''établissement [ID] en statut [pending / in_progress / ready / served], puis donne-moi la charge des postes."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='gerer-une-commande-en-direct-kds';
UPDATE public.tutorials SET titre='Configurer ses horaires et réservations', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-configurer-horaires-et-reservations-site-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-configurer-horaires-et-reservations-site-thumbnail', duree_secondes=43, how_it_works=ARRAY['Saisissez vos horaires jour par jour, coupures comprises.','Activez la page réservations, puis publiez-la : tant qu''elle est en brouillon, elle n''existe pas pour le client.','Réglez la durée d''un couvert et la capacité : c''est ce qui détermine combien de tables un créneau accepte.','Vérifiez les disponibilités réelles sur une date donnée avant d''annoncer l''ouverture.','Contrôlez enfin le domaine : une page publiée sur un domaine non validé reste invisible.']::text[], what_its_for='Les horaires du site ne sont pas un affichage : ce sont eux qui ouvrent et ferment les créneaux de réservation. Une coupure oubliée l''après-midi, et le site accepte des tables à quinze heures.', astuce_du_chef='Publiez la page réservations un jour de fermeture. Vous verrez les créneaux se fermer d''eux-mêmes — c''est la meilleure preuve que les horaires sont bien pris en compte.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Donne-moi l''état du site de l''établissement [ID] — pages publiées, URL, domaine — puis les disponibilités de réservation pour le [DATE]."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='configurer-horaires-et-reservations-site';
UPDATE public.tutorials SET titre='Voir les gagnants — historique', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-voir-les-gagnants-historique-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-voir-les-gagnants-historique-thumbnail', duree_secondes=42, how_it_works=ARRAY['Ouvrez la roue : son statut, ses lancers, ses contacts captés.','Lisez les statistiques : lancers, lots gagnés, leads. Le rapport entre les deux premiers dit si la roue est trop généreuse.','Passez aux bons émis : actifs, utilisés, expirés.','Ce sont les bons utilisés qui mesurent le retour — pas les lots gagnés.','Un taux d''expiration élevé signale un lot peu désirable, ou une durée de validité trop courte.']::text[], what_its_for='Une roue cadeaux se juge sur deux chiffres, et ce ne sont pas les lancers : les contacts captés, et les lots effectivement retirés. Un lot gagné qui n''est jamais venu au restaurant n''a rien rapporté.', astuce_du_chef='Comparez toujours les bons utilisés aux contacts captés, jamais aux lancers. Le lancer est gratuit pour le client ; c''est le déplacement qui coûte, et c''est lui qu''on mesure.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Donne-moi les statistiques de la roue [ID] de l''établissement [ID] — lancers, lots gagnés, leads — puis les bons fidélité émis par statut."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='voir-les-gagnants-historique';
UPDATE public.tutorials SET titre='Intégrer le MCP RapidoCMS & Iris', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-integrer-le-mcp-rapidocms-iris-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-integrer-le-mcp-rapidocms-iris-thumbnail', duree_secondes=48, how_it_works=ARRAY['Récupérez votre clé d''accès RapidoCMS depuis votre espace.','Ajoutez le connecteur dans votre assistant : l''adresse est cms.rapidosoftware.com/mcp.','Autorisez-le, puis vérifiez que votre marque et vos comptes connectés remontent.','Gardez les deux connecteurs séparés : FoodEatUp pour le restaurant, RapidoCMS pour le contenu.','Testez sur une demande sans effet — lister vos campagnes — avant toute publication.']::text[], what_its_for='Le connecteur RapidoCMS donne à un assistant IA la main sur le contenu : visuels, publications, pages de la vitrine. Il vient en plus du connecteur FoodEatUp, qui lui tient le restaurant — deux connecteurs, deux périmètres.', astuce_du_chef='Testez toujours par une lecture avant une écriture. Un connecteur mal autorisé publie sur le mauvais compte, et une publication ne se rattrape pas.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Liste mes campagnes RapidoCMS et les comptes sociaux connectés à ma marque."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='integrer-le-mcp-rapidocms-iris';
UPDATE public.tutorials SET titre='Retrouver la commande derrière une facture', video_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-retrouver-toutes-mes-commandes-v1', thumbnail_url='https://rapido-software.s3.eu-west-3.amazonaws.com/rapidosoftware/cms/bibliotheque/tuto-retrouver-toutes-mes-commandes-thumbnail', duree_secondes=45, how_it_works=ARRAY['Partez de la facture, et remontez à la commande qui l''a générée.','Filtrez par canal, par statut ou par date pour retrouver une commande dont vous n''avez que l''à-peu-près.','Ouvrez le détail : les articles, le client, le total, et les liens vers la facture et le devis.','Vérifiez la concordance des statuts : changer celui de la commande se répercute sur la facture et le devis.','Une commande annulée dont la facture reste ouverte est l''écart que le contrôle trouvera à votre place.']::text[], what_its_for='Chaque commande crée sa facture et son devis. Le rapprochement compte au moment du contrôle : retrouver, derrière une ligne comptable, ce qui a été servi, à qui, par quel canal — et vérifier que le statut des deux concorde.', astuce_du_chef='Rapprochez au fil de l''eau, pas en fin de mois. Un écart de statut vieux de trois semaines demande de se souvenir du service — ce que personne ne fait.', claude_prompts='[{"title": "Prompt Claude", "prompt": "Retrouve la commande liée à la facture [NUMÉRO] de l''établissement [ID], et dis-moi si le statut de la commande et celui de la facture concordent."}]'::jsonb, statut='publie', publie_le=now() WHERE slug='retrouver-toutes-mes-commandes';
COMMIT;